<script setup>
import {categories} from '../lib/rules';defineProps({form:Object,busy:Boolean});defineEmits(['save','upload','back']);
</script>
<template><section><h1>{{form.id?'修改并重新审核':'发布一件闲置'}}</h1><p>单件实物、正数价格；审核通过后公开。有效订单期间不能修改。</p><form class="card form" @submit.prevent="$emit('save')"><label>物品名称<input v-model="form.title" required maxlength="120"></label><div class="form-grid"><label>分类<select v-model="form.category"><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>价格 / 元<input v-model="form.price" type="number" min="0.01" max="9999999999.99" step="0.01" required></label></div><label>物品描述<textarea v-model="form.description" required maxlength="5000" rows="5" placeholder="请如实描述成色和瑕疵，不填写私人联系方式。"/></label><label>图片（JPEG/PNG，最多5MB）<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="$emit('upload',$event)"></label><img v-if="form.image_id" :src="'/api/assets/'+form.image_id" class="preview" alt="物品图片预览"><div class="actions"><button class="primary" :disabled="busy||!form.image_id">提交审核</button><button type="button" @click="$emit('back')">返回我的发布</button></div></form></section></template>
